#include <bits/stdc++.h>
using namespace std;

constexpr long long MOD = 1000000007LL;

long long modPow(long long base, long long exponent) {
    long long result = 1;
    while (exponent > 0) {
        if (exponent & 1) result = result * base % MOD;
        base = base * base % MOD;
        exponent >>= 1;
    }
    return result;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int f, w, h;
    cin >> f >> w >> h;

    int limit = f + w;
    vector<long long> factorial(limit + 1), inverseFactorial(limit + 1);

    factorial[0] = 1;
    for (int i = 1; i <= limit; ++i)
        factorial[i] = factorial[i - 1] * i % MOD;

    inverseFactorial[limit] = modPow(factorial[limit], MOD - 2);
    for (int i = limit; i > 0; --i)
        inverseFactorial[i - 1] = inverseFactorial[i] * i % MOD;

    auto combination = [&](int n, int k) -> long long {
        if (n < 0 || k < 0 || k > n) return 0;
        return factorial[n] * inverseFactorial[k] % MOD
             * inverseFactorial[n - k] % MOD;
    };

    long long numerator = 0;

    if (w == 0) {
        numerator = 1;
    } else {
        for (int u = 1; u <= f + 1; ++u) {
            if (h != 0 && 1LL * h * u > w - 1) break;

            int remaining = w - h * u - 1;
            numerator = (numerator +
                         combination(f + 1, u) *
                         combination(remaining, u - 1)) % MOD;
        }
    }

    long long denominator = combination(f + w, w);
    cout << numerator * modPow(denominator, MOD - 2) % MOD;

    return 0;
}

