#include <bits/stdc++.h>
using namespace std;

const long long MOD = 1000000007LL;

vector<long long> fact, invFact;

long long binpow(long long base, long long exp) {
    long long result = 1;
    while (exp > 0) {
        if (exp & 1) result = result * base % MOD;
        base = base * base % MOD;
        exp >>= 1;
    }
    return result;
}

void build(int n) {
    fact.resize(n + 1);
    invFact.resize(n + 1);

    fact[0] = 1;
    for (int i = 1; i <= n; ++i)
        fact[i] = fact[i - 1] * i % MOD;

    invFact[n] = binpow(fact[n], MOD - 2);
    for (int i = n; i > 0; --i)
        invFact[i - 1] = invFact[i] * i % MOD;
}

long long C(int n, int r) {
    if (n < 0 || r < 0 || r > n) return 0;
    return fact[n] * invFact[r] % MOD * invFact[n - r] % MOD;
}

long long num(int r, int b, int k) {
    if (b == 0) return 1;

    long long ans = 0;
    for (int u = 1; u <= r + 1 && (k == 0 || u <= (b - 1) / k); ++u) {
        ans = (ans + C(r + 1, u) * C(b - k * u - 1, u - 1)) % MOD;
    }
    return ans;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int f, w, h;
    cin >> f >> w >> h;

    build(f + w);

    long long numerator = num(f, w, h);
    long long denominator = C(f + w, w);

    cout << numerator * binpow(denominator, MOD - 2) % MOD;
    return 0;
}

